using System.Net;
using System.Windows;
using SysAdminAssistant.Core;
namespace SysAdminAssistant.Desktop;
public partial class MainWindow
{
    private async Task EditServerNetworks(){if(!remote.CurrentUser.Administrator)throw new UnauthorizedAccessException(global::SysAdminAssistant.Core.ProductText.Get("Доверенные сети изменяет только главный администратор"));var view=await remote.GetAsync<ServerNetworksView>("api/server-networks",lifetime.Token);var form=new FormDialog(this,"Доверенные сети сервера").Text("networks","Частные подсети CIDR · одна на строку",string.Join("\n",view.Networks),true).TextHeight("networks",200).Note("Ваш адрес на сервере: "+view.Peer+". Разрешение действует для клиентов и входящих отчётов агентов. Это не список адресов назначения, разрешённых самому агенту: он задаётся отдельно в его установочном пакете.\n"+view.FirewallStatus+"\nИзменения применяются без перезапуска. Удалённая подсеть немедленно потеряет доступ.");string[] Read()=>ServerNetworkRules.Validate(form.Value("networks").Split(new[]{'\n','\r',';',','},StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries));form.Validate=()=>{_=Read();return null;};if(form.ShowDialog()!=true)return;var next=Read();bool disconnect=!ServerNetworkRules.Allows(next,IPAddress.Parse(view.Peer));if(disconnect&&!Confirm(this,"Новые сети исключают ваш адрес "+view.Peer+". После сохранения подключиться отсюда не получится. Продолжить?"))return;var result=await remote.PostAsync<ServerNetworksSave,ServerNetworksView>("api/server-networks",new(next,view.Revision,disconnect),lifetime.Token);new FormDialog(this,"Доверенные сети · результат").Note(result.FirewallStatus+"\nДля Firewall при необходимости выполните эту команду в PowerShell от администратора на сервере. Существующие правила межсетевых экранов вне сервера не меняются.").Text("command","Команда Windows Firewall",result.FirewallCommand,true,true).TextHeight("command",130).ViewOnly().ShowDialog();}
}
